from __future__ import annotations

"""Models for a Microsoft Graph delta query response.

A delta query returns a stream of pages. Each page has a ``value`` array of
entities that changed since the last round. Most entries are upserts (a user or
group member that was created or modified). Some entries are *tombstones*: they
carry an ``@removed`` object such as ``{"reason": "deleted"}`` or
``{"reason": "changed"}`` and mean the entity must be dropped from the local
mirror, not written into it.

Pages chain through ``@odata.nextLink``. The final page instead carries
``@odata.deltaLink``; the token embedded in that link is what the next delta
round must replay from. A ``nextLink`` token only walks the current round.
"""

from dataclasses import dataclass


@dataclass(frozen=True)
class DeltaEntry:
    """One element of a page's ``value`` array, already classified."""

    entity_id: str
    removed: bool
    removed_reason: str
    fields: dict

    def __post_init__(self) -> None:
        if not self.entity_id.strip():
            raise ValueError("entity_id is required")
        if self.removed and not self.removed_reason:
            raise ValueError("a removed entry must carry a reason")

    def is_tombstone(self) -> bool:
        return self.removed

    def is_upsert(self) -> bool:
        return not self.removed

    @property
    def display_name(self) -> str:
        return str(self.fields.get("displayName", ""))


@dataclass(frozen=True)
class DeltaPage:
    """A single page of a delta response.

    Exactly one of ``next_link`` / ``delta_link`` is expected to be set. A page
    with ``delta_link`` is the last page of the round.
    """

    entries: tuple[DeltaEntry, ...]
    next_link: str | None = None
    delta_link: str | None = None

    def is_final(self) -> bool:
        return self.delta_link is not None

    def has_next(self) -> bool:
        return self.next_link is not None

    def upserts(self) -> tuple[DeltaEntry, ...]:
        return tuple(e for e in self.entries if e.is_upsert())

    def tombstones(self) -> tuple[DeltaEntry, ...]:
        return tuple(e for e in self.entries if e.is_tombstone())

    def entry_count(self) -> int:
        return len(self.entries)


@dataclass(frozen=True)
class DeltaResult:
    """The folded outcome of applying a full round of pages."""

    upserted_ids: tuple[str, ...]
    removed_ids: tuple[str, ...]
    page_count: int
    next_delta_token: str

    def applied_count(self) -> int:
        return len(self.upserted_ids) + len(self.removed_ids)

    def touched_ids(self) -> tuple[str, ...]:
        return tuple(list(self.upserted_ids) + list(self.removed_ids))

    def has_token(self) -> bool:
        return bool(self.next_delta_token)


def token_from_link(link: str | None) -> str:
    """Pull the ``$deltatoken`` / ``$skiptoken`` value out of a Graph link.

    Graph links look like ``https://graph.microsoft.com/v1.0/users/delta?$deltatoken=ABC``
    (final page) or ``...?$skiptoken=XYZ`` (intermediate page). We only keep the
    opaque token value; the host and path are not replayed directly.
    """

    if not link:
        return ""
    _, _, query = link.partition("?")
    if not query:
        return ""
    for part in query.split("&"):
        name, _, value = part.partition("=")
        if name in ("$deltatoken", "$skiptoken"):
            return value
    return ""


def make_entry(entity_id: str, **fields: object) -> DeltaEntry:
    """Build a plain upsert entry for tests and fixtures."""

    return DeltaEntry(
        entity_id=entity_id,
        removed=False,
        removed_reason="",
        fields=dict(fields),
    )


def make_tombstone(entity_id: str, reason: str = "deleted") -> DeltaEntry:
    """Build a tombstone (removed) entry for tests and fixtures."""

    return DeltaEntry(
        entity_id=entity_id,
        removed=True,
        removed_reason=reason,
        fields={},
    )

