from __future__ import annotations

"""Turn raw Graph delta JSON pages into ``DeltaPage`` / ``DeltaEntry`` models.

The shape we parse looks like::

    {
        "value": [
            {"id": "u1", "displayName": "Ada"},
            {"id": "u2", "@removed": {"reason": "deleted"}}
        ],
        "@odata.nextLink": "https://graph.microsoft.com/v1.0/users/delta?$skiptoken=ABC"
    }

The last page swaps ``@odata.nextLink`` for ``@odata.deltaLink``. An entry that
carries an ``@removed`` object is a tombstone regardless of whatever other
fields it still echoes back.
"""

from delta_models import DeltaEntry, DeltaPage, token_from_link

VALID_REMOVED_REASONS = ("deleted", "changed")


def parse_entry(raw: dict) -> DeltaEntry:
    """Classify one element of a page's ``value`` array."""

    if not isinstance(raw, dict):
        raise ValueError("delta entry must be an object")

    entity_id = str(raw.get("id", "")).strip()
    if not entity_id:
        raise ValueError("delta entry is missing id")

    removed_block = raw.get("@removed")
    if removed_block is not None:
        reason = _removed_reason(removed_block)
        return DeltaEntry(
            entity_id=entity_id,
            removed=True,
            removed_reason=reason,
            fields={},
        )

    fields = {k: v for k, v in raw.items() if not k.startswith("@") and k != "id"}
    return DeltaEntry(
        entity_id=entity_id,
        removed=False,
        removed_reason="",
        fields=fields,
    )


def _removed_reason(removed_block: object) -> str:
    """Normalize the ``@removed`` payload into a reason string.

    Graph usually sends ``{"reason": "deleted"}`` but older payloads sometimes
    send the bare string ``"changed"``. Anything unrecognized still counts as a
    removal; we just fall back to a generic reason rather than dropping it.
    """

    if isinstance(removed_block, dict):
        reason = str(removed_block.get("reason", "")).strip()
    else:
        reason = str(removed_block).strip()
    if not reason:
        return "deleted"
    return reason


def parse_page(raw: dict) -> DeltaPage:
    """Parse a full page object into a ``DeltaPage``."""

    if not isinstance(raw, dict):
        raise ValueError("delta page must be an object")
    value = raw.get("value")
    if not isinstance(value, list):
        raise ValueError("delta page is missing a value array")

    entries = tuple(parse_entry(item) for item in value)
    next_link = raw.get("@odata.nextLink")
    delta_link = raw.get("@odata.deltaLink")

    if next_link is not None and delta_link is not None:
        raise ValueError("a page cannot carry both nextLink and deltaLink")

    return DeltaPage(
        entries=entries,
        next_link=next_link,
        delta_link=delta_link,
    )


def parse_pages(raws: list[dict]) -> list[DeltaPage]:
    """Parse a list of raw page objects in arrival order."""

    return [parse_page(raw) for raw in raws]


def page_next_token(page: DeltaPage) -> str:
    """Token to continue *this round* (empty once the round is done)."""

    return token_from_link(page.next_link)


def page_delta_token(page: DeltaPage) -> str:
    """Token to start the *next round* (empty unless this is the final page)."""

    return token_from_link(page.delta_link)


def is_well_formed(raw: dict) -> bool:
    """Cheap shape check used by callers that prefer not to raise."""

    try:
        parse_page(raw)
    except ValueError:
        return False
    return True


def count_tombstones(pages: list[DeltaPage]) -> int:
    return sum(len(page.tombstones()) for page in pages)


def count_upserts(pages: list[DeltaPage]) -> int:
    return sum(len(page.upserts()) for page in pages)

