from __future__ import annotations

"""Local mirror of directory entities kept in step with Microsoft Graph.

The mirror is a flat ``id -> record`` map. Downstream access checks read this
map directly, so a record that lingers after the source entity was deleted
keeps granting access it should not.
"""

from dataclasses import dataclass, field


@dataclass
class MirrorStore:
    _rows: dict[str, dict] = field(default_factory=dict)

    def upsert(self, entity_id: str, fields: dict) -> dict:
        record = dict(fields)
        record["id"] = entity_id
        self._rows[entity_id] = record
        return record

    def remove(self, entity_id: str) -> bool:
        """Drop an entity from the mirror. Returns True if it existed."""

        if entity_id in self._rows:
            del self._rows[entity_id]
            return True
        return False

    def get(self, entity_id: str) -> dict | None:
        return self._rows.get(entity_id)

    def has(self, entity_id: str) -> bool:
        return entity_id in self._rows

    def ids(self) -> list[str]:
        return sorted(self._rows)

    def count(self) -> int:
        return len(self._rows)

    def records(self) -> list[dict]:
        return list(self._rows.values())

    def display_name_of(self, entity_id: str) -> str | None:
        row = self._rows.get(entity_id)
        if row is None:
            return None
        return str(row.get("displayName", ""))

    def field_of(self, entity_id: str, key: str) -> object:
        row = self._rows.get(entity_id)
        if row is None:
            return None
        return row.get(key)

    def snapshot(self) -> dict[str, dict]:
        return {eid: dict(row) for eid, row in self._rows.items()}

    def is_empty(self) -> bool:
        return not self._rows

    def clear(self) -> None:
        self._rows.clear()

    def bulk_upsert(self, records: list[tuple[str, dict]]) -> int:
        for entity_id, fields in records:
            self.upsert(entity_id, fields)
        return len(records)

    def __len__(self) -> int:
        return len(self._rows)

    def __contains__(self, entity_id: object) -> bool:
        return entity_id in self._rows


@dataclass
class ApplyReport:
    """What a single apply pass did to the mirror."""

    upserted_ids: list[str] = field(default_factory=list)
    removed_ids: list[str] = field(default_factory=list)
    skipped_ids: list[str] = field(default_factory=list)

    def record_upsert(self, entity_id: str) -> None:
        self.upserted_ids.append(entity_id)

    def record_remove(self, entity_id: str) -> None:
        self.removed_ids.append(entity_id)

    def record_skip(self, entity_id: str) -> None:
        self.skipped_ids.append(entity_id)

    def merge(self, other: "ApplyReport") -> None:
        self.upserted_ids.extend(other.upserted_ids)
        self.removed_ids.extend(other.removed_ids)
        self.skipped_ids.extend(other.skipped_ids)

    def total(self) -> int:
        return len(self.upserted_ids) + len(self.removed_ids)

    def as_dict(self) -> dict[str, object]:
        return {
            "upserted": list(self.upserted_ids),
            "removed": list(self.removed_ids),
            "skipped": list(self.skipped_ids),
            "upserted_count": len(self.upserted_ids),
            "removed_count": len(self.removed_ids),
        }


def build_mirror(seed: dict[str, dict] | None = None) -> MirrorStore:
    store = MirrorStore()
    for entity_id, fields in (seed or {}).items():
        store.upsert(entity_id, fields)
    return store

