from __future__ import annotations

"""Persistence of the delta token between sync rounds.

Each connector instance owns one sync cursor per resource (for example
``users`` or ``groups/{id}/members``). After a round finishes, the token from
the final page's ``deltaLink`` is stored here so the next round resumes from
exactly the set of changes that happened after this round. Storing the wrong
token means the next round either replays the current page chain or starts a
full resync.
"""

from dataclasses import dataclass, field

from delta_models import DeltaPage
from delta_parser import page_next_token


@dataclass
class SyncState:
    _tokens: dict[str, str] = field(default_factory=dict)
    _round_counts: dict[str, int] = field(default_factory=dict)

    def token_for(self, resource: str) -> str:
        return self._tokens.get(resource, "")

    def has_token(self, resource: str) -> bool:
        return bool(self._tokens.get(resource))

    def set_token(self, resource: str, token: str) -> None:
        self._tokens[resource] = token

    def clear(self, resource: str) -> None:
        self._tokens.pop(resource, None)

    def rounds_completed(self, resource: str) -> int:
        return self._round_counts.get(resource, 0)

    def _bump_round(self, resource: str) -> None:
        self._round_counts[resource] = self._round_counts.get(resource, 0) + 1

    def record_round(self, resource: str, pages: list[DeltaPage]) -> str:
        """Persist the cursor for the next round given the round's pages.

        We walk the pages and keep the continuation cursor each one exposes,
        stashing the last cursor we saw under the resource key so the next round
        picks up after the changes we just applied.
        """

        token = ""
        for page in pages:
            cursor = self._extract_cursor(page)
            if cursor:
                token = cursor
        self._tokens[resource] = token
        self._bump_round(resource)
        return token

    def _extract_cursor(self, page: DeltaPage) -> str:
        # Read the continuation cursor that walks the page chain for this round.
        return page_next_token(page)

    def resources(self) -> list[str]:
        return sorted(self._tokens)

    def as_dict(self) -> dict[str, str]:
        return dict(self._tokens)

    def is_fresh(self, resource: str) -> bool:
        """A resource never synced has no stored cursor yet."""

        return resource not in self._tokens


def build_state(seed: dict[str, str] | None = None) -> SyncState:
    state = SyncState()
    for resource, token in (seed or {}).items():
        state.set_token(resource, token)
